"""Recover the period from a measured spectral peak (continued fractions)."""
from __future__ import annotations

from fractions import Fraction
from math import gcd
from typing import List, Optional, Tuple


def continued_fraction(num: int, den: int) -> List[int]:
    """Continued-fraction expansion of num/den."""
    terms: List[int] = []
    while den:
        q, num, den = num // den, den, num % den
        terms.append(q)
    return terms


def convergents(terms: List[int]) -> List[Fraction]:
    """All convergents of a continued-fraction expansion."""
    out: List[Fraction] = []
    for i in range(1, len(terms) + 1):
        f = Fraction(terms[i - 1])
        for t in reversed(terms[: i - 1]):
            f = t + 1 / f
        out.append(f)
    return out


def period_from_measurement(k: int, n: int, bound: Optional[int] = None) -> int:
    """Denominator of the best convergent of k/n with denominator <= bound.

    In the exact-period regime (r | n) the measured peak is k = j*m with
    n = m*r; if gcd(j, r) = 1 then k/n = j/r is already reduced and the
    denominator returned is exactly r. Cost: O(log n) arithmetic operations.
    """
    if bound is None:
        return Fraction(k, n).denominator
    best = 1
    for c in convergents(continued_fraction(k, n)):
        if c.denominator <= bound:
            best = c.denominator
    return best


def verify_order(a: int, N: int, r: int) -> bool:
    """Check that r really is the multiplicative order of a modulo N."""
    if pow(a, r, N) != 1:
        return False
    return all(pow(a, d, N) != 1 for d in range(1, r))


def useful_peaks(m: int, r: int) -> Tuple[List[int], float]:
    """Peaks j*m with gcd(j, r) = 1, and the per-run success probability."""
    js = [j for j in range(r) if gcd(j, r) == 1]
    return [j * m for j in js], len(js) / r


if __name__ == "__main__":
    m, r = 8, 6
    peaks, prob = useful_peaks(m, r)
    for k in peaks:
        assert period_from_measurement(k, m * r) == r
    print("useful peaks", peaks, "success probability", prob)
